43	const PROCESSING_FEE = 5;
44	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
45	const BASE_PREMIUMS: Record<string, number> = {
46	  sword: 100,
47	  amulet: 60,
48	  staff: 80,
49	  potion: 40,
50	  rune: 25,
51	  moonstone: 25,
52	};
53	
54	const COMPONENT_BLOCK_SIZE = 3;
55	const COMPONENT_BLOCK_PREMIUM = 60;
56	
57	const countByType = (items: Item[]): Map<string, number> => {
58	  const counts = new Map<string, number>();
59	  for (const item of items) {
60	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
61	  }
62	
63	  return counts;
64	};
65	
66	const basePremiumForType = (type: string, count: number): number =>
67	  count === COMPONENT_BLOCK_SIZE
68	    ? COMPONENT_BLOCK_PREMIUM
69	    : count * BASE_PREMIUMS[type];
70	
71	const sumBasePremiums = (items: Item[]): number =>
72	  [...countByType(items)].reduce(
73	    (sum, [type, count]) => sum + basePremiumForType(type, count),
74	    0,
75	  );
76	
77	const quote = (step: QuoteStep): StepResult => {
78	  const basePremium = sumBasePremiums(step.items);
79	  const firstInsuranceSurcharge = basePremium * FIRST_INSURANCE_SURCHARGE_RATE;
80	
81	  return {
82	    premium: Math.ceil(basePremium + firstInsuranceSurcharge + PROCESSING_FEE),
83	  };
84	};
85	
86	const runStep = (step: Step): StepResult => {
87	  switch (step.op) {
88	    case "quote":
89	      return quote(step);
90	    default:
91	      throw new Error(`Unsupported step: ${step.op}`);
92	  }
93	};
94	
95	export const runScenario = (scenario: Scenario): ScenarioResult => ({
96	  results: scenario.steps.map(runStep),
97	});
